fun importAiSetupJson(json: String, onResult: (errors: List<String>, profilesAdded: Int, medicationsAdded: Int) -> Unit) {
    viewModelScope.launch {
        val (payload, parseError) = AiSetupImportValidator.parseJson(json)
        if (payload == null) {
            onResult(listOf(parseError ?: getApplication<Application>().getString(R.string.error_failed_parse_ai_json)), 0, 0)
            return@launch
        }
        val validationErrors = AiSetupImportValidator.validate(payload)
        if (validationErrors.isNotEmpty()) {
            onResult(validationErrors, 0, 0)
            return@launch
        }
        payload.profiles.forEach {
            profileRepository.insert(
                Profile(name = it.name, kind = ProfileKind.valueOf(it.kind.trim().uppercase()), phoneNumber = it.phoneNumber),
            )
        }
        payload.medications.forEach {
            val minIntervalMinutes = it.minIntervalHours?.let { hours -> (hours * 60).toInt() }
            medicationRepository.insert(
                Medication(name = it.name, defaultDose = it.defaultDose, minIntervalMinutes = minIntervalMinutes),
            )
        }
        onResult(emptyList(), payload.profiles.size, payload.medications.size)
    }
}
